contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(uint256 ethAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (ethAmount)); require(ethAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= ethAmount);

        address caller = address(this);
        uint256 preBal = c.balanceOf(caller); if (__ESBMC_reverted()) return;
        uint256 preRemaining = c.totalRemaining(); if (__ESBMC_reverted()) return;
        uint256 preDistributed = c.totalDistributed(); if (__ESBMC_reverted()) return;
        uint256 preValue = c.value(); if (__ESBMC_reverted()) return;
        bool preBlacklisted = c.blacklist(caller); if (__ESBMC_reverted()) return;

        c.getTokens{value: ethAmount}(); if (__ESBMC_reverted()) return;

        uint256 postBal = c.balanceOf(caller); if (__ESBMC_reverted()) return;
        uint256 postRemaining = c.totalRemaining(); if (__ESBMC_reverted()) return;
        uint256 postDistributed = c.totalDistributed(); if (__ESBMC_reverted()) return;
        uint256 postValue = c.value(); if (__ESBMC_reverted()) return;
        bool postBlacklisted = c.blacklist(caller); if (__ESBMC_reverted()) return;

        uint256 added = preValue < preRemaining ? preValue : preRemaining;

        assert(
            postBal - preBal == added &&
            preRemaining - postRemaining == added &&
            postDistributed - preDistributed == added &&
            preValue - postValue == added / 100000 &&
            (postBlacklisted == true || preBlacklisted == true)
        );
    }
}

